// presets.js — curated looks. A preset sets style only (wreath, paint, type, background); the user's text stays.
// `layout` (an id from layouts.js) also arranges the words, for the few looks built around one (ribbon, medallion, big year). All procedural: inspired by festival classics,
// heraldic and Empire wreaths, Victorian engravings, Deco ornament and botanical plates, not traced from anyone's artwork.
// Each preset belongs to a group, shown as a heading in the picker.
const gold = (angle = 28) => ({ type: 'metal', metal: 'gold', scope: 'leaf', angle });
const metal = (m, scope = 'leaf', angle = 28) => ({ type: 'metal', metal: m, scope, angle });
const lin = (stops, angle = 0, scope = 'whole') => ({ type: 'linear', stops, angle, scope });
const type = (hero, small = hero, o = {}) => ({
  eyebrow: { font: small, weight: o.sw ?? 700, case: 'upper', track: o.st ?? 0.2 },
  sub: { font: small, weight: o.sw ?? 700, case: 'upper', track: o.st ?? 0.2 },
  hero: { font: hero, weight: o.hw ?? 800, case: o.hc ?? 'upper', track: o.ht ?? 0.01, italic: !!o.hi },
  big: { font: hero, weight: o.hw ?? 800, case: 'asis', track: -0.01 },
  arc: { font: small, weight: o.sw ?? 700, case: 'upper', track: 0.28 },
});
const ink = (c, bg) => ({ paint: { branch: c, depth: 0 }, text: { paint: c, sub: c }, canvas: { bg } });

export const GROUPS = ['Festival gold', 'Vintage & engraved', 'Botanical', 'Modern & minimal', 'Deco & geometric', 'Colour & pop', 'Badges', 'Forms'];

const P = (group, name, doc, extra = {}) => ({ group, name, doc, ...extra });
const G1 = 'Festival gold', G2 = 'Vintage & engraved', G3 = 'Botanical', G4 = 'Modern & minimal', G5 = 'Deco & geometric', G6 = 'Colour & pop', G7 = 'Forms', G8 = 'Badges';
// the branchless form with a frame round the words (seals and medals carry the status and year in their band)
const badge = (kind, o = {}) => ({ form: 'text', frame: { kind, ...o } });

